type CardSlots = {
  header?: React.ReactNode;
  body?: React.ReactNode;
  footer?: React.ReactNode;
};

function Card({ header, body, footer }: CardSlots) {
  return (
    <div className="card">
      {header && <div className="card-header">{header}</div>}
      {body && <div className="card-body">{body}</div>}
      {footer && <div className="card-footer">{footer}</div>}
    </div>
  );
}

// Usage
<Card
  header={<h2>Profile</h2>}
  body={<p>User bio goes here.</p>}
  footer={<button>Follow</button>}
/>

interface DataListProps<T> {
  data: T[];
  loading: boolean;
  error: Error | null;
  renderItem: (item: T) => React.ReactNode;
  renderEmpty?: () => React.ReactNode;
  renderError?: (error: Error) => React.ReactNode;
}

function DataList<T>({
  data,
  loading,
  error,
  renderItem,
  renderEmpty,
  renderError,
}: DataListProps<T>) {
  if (loading) return <div>Loading...</div>;
  if (error && renderError) return renderError(error);
  if (data.length === 0 && renderEmpty) return renderEmpty();

  return (
    <ul className="data-list">
      {data.map((item, i) => (
        <li key={i}>{renderItem(item)}</li>
      ))}
    </ul>
  );
}

// Usage
<DataList
  data={users}
  loading={isLoading}
  error={error}
  renderItem={(user) => (
    <div className="user-card">
      <img src={user.avatar} alt={user.name} />
      <span>{user.name}</span>
    </div>
  )}
  renderEmpty={() => <p>No users found.</p>}
/>

type DashboardSlots = {
  header?: React.ReactNode;
  sidebar?: React.ReactNode;
  main?: React.ReactNode;
  footer?: React.ReactNode;
};

function DashboardLayout({ slots }: { slots: DashboardSlots }) {
  return (
    <div className="dashboard">
      {slots.header && (
        <header className="dashboard-header">{slots.header}</header>
      )}
      <div className="dashboard-body">
        {slots.sidebar && (
          <aside className="dashboard-sidebar">{slots.sidebar}</aside>
        )}
        <main className="dashboard-main">{slots.main}</main>
      </div>
      {slots.footer && (
        <footer className="dashboard-footer">{slots.footer}</footer>
      )}
    </div>
  );
}

// Usage
<DashboardLayout
  slots={{
    header: <TopBar user={user} />,
    sidebar: <NavMenu items={navItems} />,
    main: <DashboardContent data={data} />,
    footer: <Copyright />,
  }}
/>
